import{_ as a,c as e,o as s,a as n}from"./app.7858d469.js";const f=JSON.parse('{"title":"HuggingFace Integration","description":"","frontmatter":{},"headers":[{"level":2,"title":"Search for Models","slug":"search-for-models","link":"#search-for-models","children":[]},{"level":2,"title":"Pull a Model","slug":"pull-a-model","link":"#pull-a-model","children":[]},{"level":2,"title":"Features","slug":"features","link":"#features","children":[]},{"level":2,"title":"Model Format Support","slug":"model-format-support","link":"#model-format-support","children":[]},{"level":2,"title":"After Pulling","slug":"after-pulling","link":"#after-pulling","children":[]},{"level":2,"title":"Troubleshooting","slug":"troubleshooting","link":"#troubleshooting","children":[]}],"relativePath":"guide/huggingface.md"}'),l={name:"guide/huggingface.md"},o=n(`<h1 id="huggingface-integration" tabindex="-1">HuggingFace Integration <a class="header-anchor" href="#huggingface-integration" aria-hidden="true">#</a></h1><p>Pull GGUF models directly from HuggingFace Hub with Lychee&#39;s <code>hf</code> command.</p><h2 id="search-for-models" tabindex="-1">Search for Models <a class="header-anchor" href="#search-for-models" aria-hidden="true">#</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki"><code><span class="line"><span style="color:#676E95;"># Search the catalog</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee hf search llama</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># Search for specific model types</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee hf search mistral</span></span>
<span class="line"></span></code></pre></div><h2 id="pull-a-model" tabindex="-1">Pull a Model <a class="header-anchor" href="#pull-a-model" aria-hidden="true">#</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki"><code><span class="line"><span style="color:#676E95;"># Download recommended quantization</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee hf pull microsoft/Phi-3-mini-4k-instruct-gguf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># List available quantizations</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee hf pull bartowski/Meta-Llama-3.1-8B-Instruct-GGUF --list</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># Download specific quantization</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee hf pull bartowski/Meta-Llama-3.1-8B-Instruct-GGUF --quant q5_k_m</span></span>
<span class="line"></span></code></pre></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-hidden="true">#</a></h2><ul><li><strong>Concurrent Downloads</strong>: Multi-shard parallel downloading for maximum speed</li><li><strong>Resume Support</strong>: Interrupted downloads resume from where they stopped</li><li><strong>SHA256 Verification</strong>: Automatic integrity checking of downloaded files</li><li><strong>Quantization Selection</strong>: Choose from all available GGUF quantization variants</li><li><strong>Catalog Search</strong>: Search HuggingFace for GGUF models without leaving the CLI</li></ul><h2 id="model-format-support" tabindex="-1">Model Format Support <a class="header-anchor" href="#model-format-support" aria-hidden="true">#</a></h2><p>Lychee&#39;s <code>hf pull</code> works with any GGUF-format model on HuggingFace. Look for repositories with:</p><ul><li><code>*-gguf</code> suffix (e.g., <code>bartowski/Meta-Llama-3.1-8B-Instruct-GGUF</code>)</li><li>Models from popular uploaders: <code>bartowski</code>, <code>TheBloke</code>, <code>MaziyarPanahi</code>, etc.</li></ul><h2 id="after-pulling" tabindex="-1">After Pulling <a class="header-anchor" href="#after-pulling" aria-hidden="true">#</a></h2><p>Once downloaded, use the model like any other:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki"><code><span class="line"><span style="color:#676E95;"># Run the model</span></span>
<span class="line"><span style="color:#A6ACCD;">lychee run Phi-3-mini-4k-instruct</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># Use via API</span></span>
<span class="line"><span style="color:#A6ACCD;">curl http://localhost:11434/api/chat \\</span></span>
<span class="line"><span style="color:#A6ACCD;">  -H </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Content-Type: application/json</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> \\</span></span>
<span class="line"><span style="color:#A6ACCD;">  -d </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">{</span></span>
<span class="line"><span style="color:#C3E88D;">    &quot;model&quot;: &quot;Phi-3-mini-4k-instruct&quot;,</span></span>
<span class="line"><span style="color:#C3E88D;">    &quot;messages&quot;: [{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;Hello!&quot;}]</span></span>
<span class="line"><span style="color:#C3E88D;">  }</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-hidden="true">#</a></h2><table><thead><tr><th>Issue</th><th>Solution</th></tr></thead><tbody><tr><td>Download fails</td><td>Check internet connection; retry resumes from last position</td></tr><tr><td>SHA256 mismatch</td><td>Delete the partial download and retry</td></tr><tr><td>Model not found</td><td>Verify repository name and GGUF format availability</td></tr><tr><td>Slow downloads</td><td>Ensure concurrent shard support is enabled</td></tr></tbody></table>`,16),t=[o];function r(i,c,p,d,u,h){return s(),e("div",null,t)}const m=a(l,[["render",r]]);export{f as __pageData,m as default};
